(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.EmberAdvancedAuthoring=api;})(globalThis,()=>{
 const defaults={intensity:1,scale:1,color:'#ffffff'};
 function validate(e){const m=e.master;if(m!==undefined){if(!m||!Number.isFinite(m.intensity)||m.intensity<0||m.intensity>10||!Number.isFinite(m.scale)||m.scale<.1||m.scale>10||!/^#[0-9a-f]{6}$/i.test(m.color))throw Error('Invalid whole-effect controls');}if(e.simulation!==undefined&&!['cpu','gpu'].includes(e.simulation))throw Error('Choose CPU or GPU simulation');if(e.gpuAmount!==undefined&&(!Number.isInteger(e.gpuAmount)||e.gpuAmount<5||e.gpuAmount>100000))throw Error('Use 5–100,000 GPU particles per second');if(e.motion==='orbit'&&(e.surface||e.sceneCollision&&e.sceneCollision!=='off'))throw Error('Surface emission and scene collisions need free particle movement');if(e.simulation==='gpu'&&e.eventRules?.length)throw Error('Niagara event responses require CPU simulation');if(e.sceneCollision!==undefined&&!['off','bounce','kill'].includes(e.sceneCollision))throw Error('Invalid scene collision response');if(e.surface!==undefined){const s=e.surface;if(!s||!['static','skeletal'].includes(s.kind)||!/^\/Game\/[A-Za-z0-9_/]+\.[A-Za-z0-9_]+$/.test(s.asset)||!Array.isArray(s.points)||!s.points.length||s.points.length>2048||s.points.some(p=>!Array.isArray(p)||p.length!==3||p.some(n=>!Number.isFinite(n)||Math.abs(n)>100000)))throw Error('Invalid mesh emission surface');}if(e.attachment!==undefined){const a=e.attachment;if(!a||typeof a.actor!=='string'||a.actor.length>100||typeof a.socket!=='string'||a.socket.length>100||/[\r\n]/.test(a.actor+a.socket))throw Error('Invalid actor attachment');}}
 const decode=v=>v<=.04045?v/12.92:Math.pow((v+.055)/1.055,2.4),encode=v=>v<=.0031308?v*12.92:1.055*Math.pow(v,1/2.4)-.055;
 function tint(color,filter){const out=[1,3,5].map(i=>Math.round(encode(decode(parseInt(color.slice(i,i+2),16)/255)*decode(parseInt(filter.slice(i,i+2),16)/255))*255).toString(16).padStart(2,'0'));return '#'+out.join('');}
 function render(group,master=defaults){const m={...defaults,...master},effect={...group.effect,color:tint(group.effect.color,m.color),endColor:tint(group.effect.endColor||'#ff4f28',m.color)};if(effect.lifetime?.color)effect.lifetime={...effect.lifetime,color:effect.lifetime.color.map(stop=>({...stop,value:tint(stop.value,m.color)}))};const scale=m.scale;if(effect.ribbonWidth!==undefined)effect.ribbonWidth*=scale;return {effect,particles:scale===1?group.particles:group.particles.map(p=>({...p,x:p.x*scale,y:p.y*scale,z:p.z*scale,vx:p.vx*scale,vy:p.vy*scale,vz:p.vz*scale,size:p.size*scale}))};}
 function response(effect){const copy=JSON.parse(JSON.stringify(effect));for(const key of ['eventRules','animation','surface','attachment','master'])delete copy[key];copy.sceneCollision='off';copy.simulation='cpu';return copy;}
 function inherit(effect,context){const next=JSON.parse(JSON.stringify(effect));next.master={...defaults,...context.master};if(context.attachment)next.attachment=JSON.parse(JSON.stringify(context.attachment));else delete next.attachment;return next;}
 return {defaults,validate,tint,render,response,inherit};
});
